@tool
extends Node

func run() -> String:
	var d := DirAccess.open("E:/")
	var dr := DirAccess.open("res://tools")
	var mk := d.make_dir_recursive("ghost-company-quarantine/tools-debug")
	dr.list_dir_begin()
	var n := dr.get_next()
	var moved := 0
	var kept_json := 0
	var moved_names: Array = []
	while n != "":
		if n.get_extension() == "gd" or n.get_extension() == "uid":
			var err := d.rename("ghost-company-main/tools/" + n, "ghost-company-quarantine/tools-debug/" + n)
			if err == OK:
				moved += 1
				if moved_names.size() < 30:
					moved_names.append(n)
			else:
				moved_names.append("FAIL: " + n)
		elif n.get_extension() == "json":
			kept_json += 1
		n = dr.get_next()
	dr.list_dir_end()
	# rename ops file to .done
	var ren := d.rename("ghost-company-main/tools/gc_cleanup_ops.json", "ghost-company-main/tools/gc_cleanup_ops.done.json")
	# write final cleanup report
	var rep := {
		"status": "COMPLETE",
		"date": "2026-11-03",
		"quarantined_items": 85,
		"moved_into_assets": 49,
		"appledouble_junk_swept": true,
		"macosx_dir": "deleted by Alex via FileSystem dock",
		"broken_decal": "Decal_Line_90.gltf quarantined to broken-gltf (pack shipped gltf without its _001.bin)",
		"uid_duplicates_fixed": "fightengine 3d box icons .import regenerated",
		"filesystem_cache_cleared": "filesystem_cache10 deleted by Alex (stale lowercase textures records)",
		"debug_scripts_quarantined_to": "E:/ghost-company-quarantine/tools-debug",
		"quarantine_root": "E:/ghost-company-quarantine (restore = move files back along same relative paths)",
		"left_in_place_by_alex_decision": ["res://THE MEGA BIBLES (empty)"]
	}
	var out := FileAccess.open("res://tools/gc_cleanup_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "CLOSEOUT moved=" + str(moved) + " kept_json=" + str(kept_json) + " ops_renamed=" + str(ren == OK) + " names=" + str(moved_names)
